import { PROVIDERS } from './providers.js';
import { originalsReleased } from './release-policy.js';
import openDataCandidates from './open-data-candidates.json' with {type:'json'};
import clcdReview from '../../crates/geod-runtime/src/datasets/clcd-reviewed-index.json' with {type:'json'};

// Current 2D product scope. Some Planned families expose a bounded partial action.
// A supported protocol is a connection path, not blanket provider entitlement.
const productCategory = provider => provider.domain === 'elevation' ? 'elevation' : provider.domain === 'radar' ? 'radar' : 'imagery';
const featured = ['earth-search','planetary-landsat','planetary-radar','planetary-vegetation','copernicus-dem','planetary-naip','planetary-modis','planetary-computer','copernicus-dem-90'];
const order = provider => featured.includes(provider.id) ? featured.indexOf(provider.id) : featured.length;
const entry = (id, name, detail, platform, mark, series, category, group, action) => ({id,name,detail,platform,mark,series,category,group,status:action ? 'ready' : 'planned',action});
// Public product recipes use the native dataset catalog and the existing pinned
// raster download path. Connector availability does not certify every tile.
const datasetActions = new Set(['worldcover', 'worldcover-composites', 'worldpop', 'jrc-water', 'glad-forest', 'etopo', 'chirps', 'nasadem', 'alos-aw3d30', 'srtm-gl1', 'hydrosheds', 'cbers-sr', 'io-lulc', 'hilda-land-use', 'worldcereal', 'deafrica-fractional-cover', 'deafrica-wofs-annual', 'wsf-settlements', 'gmw-mangroves', 'cgls-landcover', 'usgs-3dep', 'chelsa-climate', 'jaxa-amsr2-soil-moisture', 'jaxa-sgli-lst', 'jaxa-modis-ndvi', 'jaxa-palsar-fnf', 'jaxa-sgli-chla', 'jaxa-gsmap-rainfall', 'jaxa-hrlulc-japan', 'jaxa-modis-swr']);
const datasetAction = id => datasetActions.has(id) ? {kind:'dataset',datasetId:id} : undefined;
// Keep stable directory-card ids while selecting a narrowly reviewed product.
// Only products whose complete native lifecycle was accepted gain an action.
const approvedNextPublicProducts = new Set(['ghsl-smod','glad-landcover-2020','maxar-open-legacy','usgs-3dep-1m', 'cbers-wpm', 'openlandmap-nightlights', 'jaxa-sgli-sst', 'amazonia-wfi-dn',
  'jaxa-sgli-et','jaxa-sgli-et-index','jaxa-sgli-aerosol','jaxa-modis-aerosol','jaxa-amsr2-wind','jaxa-amsr2-sst','jaxa-gsmap-spi','srtm-gl3','gedi-l3-canopy','srtm15plus-bathymetry',
  'ghsl-built-surface','ghsl-built-volume','ghsl-population','eth-canopy-height','hydrosheds-accumulation','etopo-geoid','pc-hrea','pc-biodiversity','noaa-ohc','noaa-nclimgrid']);
const nextDatasetAction = id => approvedNextPublicProducts.has(id) ? {kind:'dataset',datasetId:id} : undefined;
const candidateDatasetId = source => source.id === 'cbers-4a' ? 'cbers-wpm' : source.id === 'ghsl' ? 'ghsl-smod' : source.id === 'maxar-open' ? 'maxar-open-legacy' : source.id === 'usgs-3dep-dem' ? 'usgs-3dep-1m' : source.id;
const candidateDatasetAction = source => source.id === 'geoboundaries'
  ? {kind:'vector',protocol:'geoBoundaries'}
  : ['ghsl','maxar-open','usgs-3dep-dem','cbers-4a','srtm-gl3'].includes(source.id)
  ? nextDatasetAction(candidateDatasetId(source))
  : datasetAction(candidateDatasetId(source));

